#!/usr/bin/env node
// The Claude `PreToolUse` write-authority boundary (ADR-0257 D1/D3) — increment 2 of the
// session-isolation wall, and the SEMANTIC half of it.
//
// THE OTHER HALF IS STATIC. `.claude/settings.json`'s `permissions.deny` block (generated by
// `write-authority-rules.ts`) makes the primary checkout unwritable by the file tools at zero cost,
// in-process, and — verified against the docs — even under `bypassPermissions`. That is the
// containment floor ADR-0257 D1 requires alongside a pre-tool policy. This hook is the layer that
// static rules CANNOT express: whether the target's worktree is actually claimed, whether it is
// still on the claimed branch, whether HEAD went detached, and whether a junction/symlink escapes
// the workspace (gitignore-style rules match TEXT; only `realpath` catches an escape).
//
// The two fail differently on purpose. If this hook breaks, is misconfigured, or never runs, the
// static layer still holds the lobby. If the static layer is out of date, this hook still resolves
// the real path. Neither alone is the wall.
//
// FAIL-CLOSED, WITH ONE DELIBERATE EXCEPTION. Every arm that cannot PROVE authority denies: no
// readable stdin, a target that cannot be extracted, a cwd that is not a recognised worktree, an
// unloadable decision module, an absent/expired/forged receipt. The single exception is the kill
// switch below, which is a HUMAN maintenance lever, not an agent-selectable escape (ADR-0257 D1
// allows exactly that distinction) — the agent cannot set the parent process's environment.
//
// THE SWITCH IS OFF BY DEFAULT IN THIS INCREMENT (owner call, 2026-08-01: "land it off, drain the
// fleet, then flip it on in a one-line PR"). Merging this changes NO session's behaviour. At the
// time of writing 38 of 39 registered worktrees hold no live claim and 14 are on detached HEAD, so
// switching on before a drain would refuse writes fleet-wide. The flip PR sets the default to on.
//
// CONSTRAINTS (mirroring provision-worktree.mjs / worktree-health.mjs): BARE NODE at the top level,
// zero non-builtin imports, so this file always loads. The typed decision core is imported lazily
// through tsx — and any failure to load it DENIES rather than falling open.
import { readFileSync, realpathSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import process from "node:process";

/** Tool names whose write target this boundary gates. Bash is deliberately NOT here — shell
 *  containment is a separate, unbuilt increment, and pretending otherwise would overclaim. */
const GATED_TOOLS = new Set(["Write", "Edit", "NotebookEdit"]);

/** Emit a PreToolUse deny and exit. Exit 0: the JSON verdict IS the refusal channel. */
function deny(reason) {
  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: reason,
      },
    }) + "\n",
  );
  process.exit(0);
}

/**
 * Let the call proceed under the NORMAL permission flow. Deliberately emits nothing rather than
 * `permissionDecision: "allow"`: an explicit allow would auto-approve writes the user's own settings
 * might otherwise ask about, so a security boundary that only ever REFUSES must stay silent when it
 * has nothing to refuse.
 */
function pass() {
  process.exit(0);
}

/** Read all of stdin; null when it cannot be read or parsed (which denies). */
async function readInput() {
  try {
    const chunks = [];
    for await (const chunk of process.stdin) chunks.push(chunk);
    const raw = Buffer.concat(chunks).toString("utf8").trim();
    if (raw === "") return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

/**
 * The write targets a gated tool call would touch. Returns an array (possibly EMPTY, which denies —
 * ADR-0257 D3 refuses a write-capable route whose targets cannot be extracted rather than guessing
 * it is harmless).
 */
export function extractTargets(toolName, toolInput) {
  if (toolInput === null || typeof toolInput !== "object") return [];
  const out = [];
  for (const key of ["file_path", "notebook_path"]) {
    const v = toolInput[key];
    if (typeof v === "string" && v.trim() !== "") out.push(v);
  }
  return out;
}

/** Is the wall switched on? `on`/`1`/`true` enable it; anything else (including unset) leaves it inert. */
export function wallEnabled(env) {
  const v = (env["STORYTREE_WRITE_AUTHORITY"] ?? "").trim().toLowerCase();
  return v === "on" || v === "1" || v === "true";
}

async function main() {
  if (!wallEnabled(process.env)) pass();

  const input = await readInput();
  if (input === null) {
    deny(
      "REFUSED — the write-authority boundary could not read its own hook input, so this tool call's " +
        "authority cannot be checked (ADR-0257 D3 fails closed rather than guessing).",
    );
  }

  const toolName = typeof input.tool_name === "string" ? input.tool_name : "";
  if (!GATED_TOOLS.has(toolName)) pass();

  const targets = extractTargets(toolName, input.tool_input);
  if (targets.length === 0) {
    deny(
      `REFUSED — no write target could be extracted from this ${toolName} call, so its authority ` +
        "cannot be checked (ADR-0257 D3: a write-capable route whose targets cannot be extracted is " +
        "denied, never guessed read-only).",
    );
  }

  const cwd = typeof input.cwd === "string" && input.cwd !== "" ? input.cwd : process.cwd();

  // The typed decision core, loaded lazily through tsx. ANY failure here denies — an authority
  // boundary that cannot load its own decision must not fall open. Measured ~450 ms warm, because
  // the imported graph is only these two modules plus node builtins.
  let core;
  try {
    const { register } = await import("tsx/esm/api");
    register();
    core = await import(new URL("../drive/src/write-authority-receipt.ts", import.meta.url).href);
  } catch (err) {
    deny(
      "REFUSED — the write-authority decision module could not be loaded, so authority cannot be " +
        `proven (${String(err && err.message ? err.message : err)}). If this worktree is freshly ` +
        "created, run `pnpm install` here. Failing closed is deliberate: ADR-0257 D1.",
    );
  }

  // Path-shape only, and shared with the receipt module rather than re-implemented here: a second
  // hand-rolled copy of separator/case handling is exactly how a `/`-vs-`\` bug reaches a wall.
  const located = core.locateWorktree(cwd);
  if (located === null) {
    deny(
      [
        "REFUSED — this session is not running inside a repository-minted worktree, so it holds no",
        "write authority (ADR-0255 D1, narrowed to shared checkouts by ADR-0257 D6). The primary",
        "checkout is a read-only agent lobby: read it, query the tree and the ledger, and request a",
        "workspace there — but no agent file tool may write into it.",
        "",
        'Get a claimed workspace:  pnpm storytree worktree create --node <story-id> --intent "<what>" --pg',
      ].join("\n"),
    );
  }

  const readFile = (p) => {
    try {
      return readFileSync(p, "utf8");
    } catch {
      return null;
    }
  };

  let receipt = null;
  const rp = core.receiptPath(located.primaryRoot, located.sessionId);
  const rawReceipt = readFile(rp);
  if (rawReceipt !== null) {
    let parsedJson;
    try {
      parsedJson = JSON.parse(rawReceipt);
    } catch {
      deny(`REFUSED — this session's write-authority receipt (${rp}) is not valid JSON. A receipt that cannot be parsed is not evidence of a claim (ADR-0257 D5).`);
    }
    const parsed = core.parseReceipt(parsedJson);
    if (!parsed.ok) {
      deny(`REFUSED — this session's write-authority receipt (${rp}) is not usable: ${parsed.why} (ADR-0257 D5 fails closed on a malformed or forged receipt).`);
    }
    receipt = parsed.receipt;
  }

  const decision = core.evaluateReceiptAuthority({
    rawTargets: targets,
    cwd,
    receipt,
    headBranch: receipt === null ? null : core.readHeadBranch(receipt.worktreeRoot, readFile),
    now: new Date(),
  });

  if (decision.decision === "refuse") deny(decision.reason);
  pass();
}

/** True when this module is the process entry (invoked directly), false when imported (e.g. the test). */
function isEntry() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

// Only run as the process entry — the test imports the pure helpers above without executing main().
if (isEntry()) {
  main().catch((err) => {
    // Even an unexpected crash denies. This is the arm that separates an authority boundary from a
    // landing gate: `check-declared.ts` may fail open, this may not.
    deny(
      "REFUSED — the write-authority boundary errored while deciding, so authority cannot be proven " +
        `(${String(err && err.message ? err.message : err)}). Failing closed is deliberate (ADR-0257 D1).`,
    );
  });
}
